export const playerName=value=>[...String(value||'').replace(/[\u0000-\u001f\u007f-\u009f<>]/g,'').replace(/\s+/g,' ').trim()].slice(0,20).join('')||'Driver';
export const chatText=value=>[...String(value||'').replace(/[\u0000-\u001f\u007f-\u009f]/g,' ').replace(/\s+/g,' ').trim()].slice(0,140).join('');
export const QUICK_CHATS=Object.freeze(['I got it!','Defending!','Need boost!','Nice shot!','Thanks!','Sorry!','Cuck puppy','Your my good girl.','That is not right puppy',"I’m sorry kitten",'CHAT CLIP THAAAAATTTTT...','In your net!',"I’m gonna touch it if you don’t!",'W coms mum','Not know kitten whiker']);
export function quickChats(value){return (Array.isArray(value)?value:QUICK_CHATS).map(chatText).filter(Boolean).slice(0,20);}
export function setupSocialUI(settings,{save=()=>{},send=()=>false,profile=()=>{},opened=()=>{}},root=document){
 const node=id=>root.getElementById(id),messages=[];settings.username=playerName(settings.username);settings.quickChats=quickChats(settings.quickChats);
 function presets(){const grid=node('quick-chat-buttons');grid.replaceChildren();for(const text of settings.quickChats){const button=root.createElement('button');button.type='button';button.textContent=text;button.className='secondary';button.addEventListener('click',()=>submit(text));grid.append(button);}node('custom-quick-chats').value=settings.quickChats.join('\n');}
 function submit(value){const text=chatText(value);if(!text)return;if(send(text)){node('chat-text').value='';node('chat-dialog').close();}else node('chat-status').textContent='Please wait a moment before sending another message.';}
 node('chat-send').addEventListener('click',()=>submit(node('chat-text').value));node('chat-form').addEventListener('submit',event=>{event.preventDefault();submit(node('chat-text').value);});
 node('chat-back').addEventListener('click',()=>node('chat-dialog').close());node('display-name').value=settings.username;node('display-name').addEventListener('change',()=>{settings.username=playerName(node('display-name').value);node('display-name').value=settings.username;save();profile(settings.username);});
 node('custom-quick-chats').addEventListener('change',()=>{settings.quickChats=quickChats(node('custom-quick-chats').value.split('\n'));presets();save();});node('reset-quick-chats').addEventListener('click',()=>{settings.quickChats=quickChats();presets();save();});presets();
 function receive(message){const name=playerName(message.name),text=chatText(message.text);if(!text)return;messages.push({name,text});if(messages.length>40)messages.shift();const feed=node('chat-feed');feed.replaceChildren();for(const entry of messages.slice(-6)){const line=root.createElement('p'),label=root.createElement('strong'),body=root.createElement('span');label.textContent=entry.name+': ';body.textContent=entry.text;line.append(label,body);feed.append(line);}feed.hidden=false;}
 return {receive,open(quick=false,online=false){opened();node('chat-status').textContent=online?'ALL PLAYERS':'OFFLINE · LOCAL CHAT';node('chat-title').textContent=quick?'QUICK CHAT':'TEXT CHAT';if(!node('chat-dialog').open)node('chat-dialog').showModal();(quick?node('quick-chat-buttons').querySelector('button'):node('chat-text'))?.focus();}};
}
